// Deterministic primality check for all i8 values.
// Matches the spec: prime iff n >= 2 and has no divisor k with 2 <= k < n.
fn is_prime(n: i8) -> bool {
    // Handle negatives, 0, 1.
    if n < 2 {
        return false;
    }

    // Work in i16 to avoid any edge cases around i8 arithmetic/mod.
    let nn: i16 = n as i16;

    // Candidate divisor starts at 2 and increases.
    let mut k: i16 = 2;

    // Loop structure corresponds to:
    // - invariant: nn >= 2
    // - invariant: 2 <= k <= nn
    // - invariant: for all j with 2 <= j < k, nn % j != 0
    //
    // Termination measure: nn - k (a nonnegative integer that strictly decreases).
    while k < nn {
        // If we find any divisor in [2, nn), n is not prime.
        if nn % k == 0 {
            return false;
        }

        // Progress: k increases by 1, so (nn - k) decreases by 1.
        k += 1;
    }

    // If no k in [2, nn) divides nn, then by definition nn is prime.
    true
}